package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamGlobalBank1 {
  private const val T = "විදේශ ප්‍රතිපත්තිය, ජාත්‍යන්තර සංවිධාන හා මානුෂීය නීතිය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("කිසියම් ස්වාධීන රාජ්‍යයක් වෙනත් රාජ්‍යයන් හා ජාත්‍යන්තර සංවිධාන සමඟ සබඳතා පවත්වාගෙන යාම සඳහා අනුගමනය කරන මූලධර්ම මාලාව කුමක්ද?", "විදේශ ප්‍රතිපත්තිය (Foreign Policy)", "පළාත් පාලන ප්‍රඥප්තිය", "දේශීය වරිපනම් ක්‍රමය", "සමථ මණ්ඩල නීතිය", "රටක ස්වෛරීභාවය, ජාතික ආරක්ෂාව හා ආර්ථික අභිවෘද්ධිය ආරක්ෂා කර ගැනීමට විදේශ ප්‍රතිපත්තිය මෙහෙයවේ."),
    q("ඕනෑම රටක විදේශ ප්‍රතිපත්තිය සකස් කිරීමේදී මූලිකවම අරමුණු කර ගන්නා ප්‍රධානතම සාධකය කුමක්ද?", "ජාතික අභිලාෂය හෙවත් ජාතික හිතසුව (National Interest)", "අසල්වැසි රටවල මැතිවරණ පමණක්", "පළාත් සභා සීමා නිර්ණය", "පාසල් නිවාඩු දින", "ජාතික ආරක්ෂාව, භෞමික අඛණ්ඩතාව හා ජනතාවගේ ආර්ථික සුබසිද්ධිය රැකීම ජාතික අභිලාෂයේ හරයයි."),
    q("ශ්‍රී ලංකාවේ විදේශ ප්‍රතිපත්තිය තීරණය කිරීමට බලපාන ප්‍රධානතම 'භූ-දේශපාලනික සාධකය' (Geopolitical Factor) කුමක්ද?", "ඉන්දියන් සාගරයේ ප්‍රධාන ජාත්‍යන්තර නාවික මාර්ගය මධ්‍යයේ පිහිටීම", "හිමාල කඳුවැටියට මායිම් වීම", "භූමියෙන් වට වූ ගොඩබිම් රාජ්‍යයක් වීම", "ධ්‍රැවීය හිම කලාපයේ පිහිටීම", "ලෝකයේ නැගෙනහිර හා බටහිර සම්බන්ධ කරන ඉන්දියන් සාගර කේන්ද්‍රීය පිහිටීම ශ්‍රී ලංකාවට උපායමාර්ගික වැදගත්කමක් ගෙන දේ."),
    q("සාමකාමී සාකච්ඡා, ගිවිසුම් හා සම්මුති මඟින් රාජ්‍යයන් අතර සබඳතා පවත්වා ගැනීමේ ශිල්පය හඳුන්වන්නේ කුමන නමින්ද?", "රාජ්‍යතාන්ත්‍රිකභාවය (Diplomacy)", "ආර්ථික සම්බාධක", "යුද ආක්‍රමණය", "අභ්‍යන්තර කැරලි", "යුද්ධයකින් තොරව ජාත්‍යන්තර ගැටලු විසඳීමට රාජ්‍යතාන්ත්‍රික සේවය උපකාරී වේ."),
    q("පොදුරාජ්‍ය මණ්ඩලයීය රටවල් (ශ්‍රී ලංකාව, ඉන්දියාව හා එක්සත් රාජධානිය වැනි) අතර පත් කරන ඉහළම රාජ්‍යතාන්ත්‍රික නියෝජිතයා කවුද?", "මහ කොමසාරිස් (High Commissioner)", "කොන්සල්වරයා", "විගණකාධිපති", "තේරීම් භාර නිලධාරී", "පොදුරාජ්‍ය මණ්ඩලීය රටවල් අතර මහ කොමසාරිස්වරුන්ද අනෙක් රටවලට තානාපතිවරුන්ද (Ambassadors) පත් කෙරේ."),
    q("පොදුරාජ්‍ය මණ්ඩලයට අයත් නොවන විදේශීය රටක (ජපානය, ඇමරිකාව හෝ චීනය වැනි) ශ්‍රී ලංකාව නියෝජනය කරන ඉහළම රාජ්‍යතාන්ත්‍රිකයා කවුද?", "තානාපතිවරයා (Ambassador)", "මහ කොමසාරිස්", "දිසාපති", "නගරාධිපති", "තානාපතිවරයා ජනාධිපතිවරයාගේ හා රාජ්‍යයේ නිල නියෝජිතයා ලෙස සත්කාරක රටේ ක්‍රියා කරයි."),
    q("විදේශ රටක වෙසෙන ශ්‍රී ලාංකිකයන්ගේ ගමන් බලපත්‍ර, වීසා, උප්පැන්න ලියාපදිංචිය හා වෙළඳ සේවා ඉටු කරන රාජ්‍යතාන්ත්‍රික නිලධාරියා කවුද?", "කොන්සල්වරයා (Consul)", "පළාත් ආණ්ඩුකාරවරයා", "කතානායකවරයා", "නීතිපතිවරයා", "තානාපති කාර්යාලයේ කොන්සියුලර් අංශය හා කොන්සල් කාර්යාල පුරවැසි සේවා හා වාණිජ සබඳතා සපයයි."),
    q("රාජ්‍යතාන්ත්‍රික නියෝජිතයන්ගේ වරප්‍රසාද, මුක්තිය (Immunity) හා තානාපති කාර්යාලවල ආරක්ෂාව තහවුරු කරන 1961 ජාත්‍යන්තර සම්මුතිය කුමක්ද?", "රාජ්‍යතාන්ත්‍රික සබඳතා පිළිබඳ වියානා සම්මුතිය (Vienna Convention 1961)", "මැග්නා කාර්ටා ගිවිසුම", "දඹදෙණි කතිකාවත", "ඩොනමෝර් යෝජනා", "විදේශ තානාපතිවරුන්ට බියෙන් තොරව රාජකාරි කිරීමට රාජ්‍යතාන්ත්‍රික මුක්තිය වියානා සම්මුතියෙන් ලබාදී ඇත."),
    q("1955 දී ඉන්දුනීසියාවේ පැවති ආසියානු-අප්‍රිකානු රටවල් 29ක සමුළුව 'නොබැඳි ව්‍යාපාරයේ' පදනම දැමූ සමුළුව විය. එය කුමක්ද?", "බැංඩුං සමුළුව (Bandung Conference)", "බෙල්ග්‍රේඩ් සමුළුව", "ජිනීවා සමුළුව", "කොළඹ සමුළුව", "යටත්විජිතවාදයට විරුද්ධව සහ සාමකාමී සහජීවනය වෙනුවෙන් ආසියා-අප්‍රිකා ජාතීන් බැංඩුං හිදී එක් විය."),
    q("ශ්‍රී ලංකාව නිදහසෙන් පසු සිය විදේශ ප්‍රතිපත්තියේ ප්‍රධාන මූලධර්මයක් ලෙස අනුගමනය කර ඇති ප්‍රතිපත්තිය කුමක්ද?", "නොබැඳි විදේශ ප්‍රතිපත්තිය (Non-Aligned Foreign Policy)", "යුද කඳවුරු බැඳීමේ ප්‍රතිපත්තිය", "ආක්‍රමණශීලී අධිරාජ්‍යවාදය", "සම්පූර්ණ හුදෙකලාවාදය", "සීතල යුද සමයේ ඇමරිකානු හෝ සෝවියට් බල කඳවුරුවලට නොබැඳී සියලු රටවල් සමඟ මිත්‍රශීලීව කටයුතු කිරීම ශ්‍රී ලංකාව තෝරා ගත්තේය."),
    q("1961 දී යුගෝස්ලාවියාවේදී පැවැති ප්‍රථම නොබැඳි ජාතීන්ගේ රාජ්‍ය නායක සමුළුව හඳුන්වන්නේ කුමන නමින්ද?", "බෙල්ග්‍රේඩ් සමුළුව (Belgrade Summit)", "බැංඩුං සමුළුව", "හවානා සමුළුව", "නවදිල්ලි සමුළුව", "1961 සැප්තැම්බර් මස රටවල් 25ක සහභාගිත්වයෙන් ශ්‍රී ලංකාවද සම-ආරම්භක සාමාජිකයෙකු ලෙස එක් විය."),
    q("නොබැඳි ව්‍යාපාරයේ (NAM) ප්‍රධාන නිර්මාතෘවරුන් පස්දෙනා අතරට අයත් නොවන්නේ කවුද?", "වින්ස්ටන් චර්චිල්", "ජවහර්ලාල් නේරු (ඉන්දියාව) සහ ජෝසිප් බ්‍රොස් ටිටෝ (යුගෝස්ලාවියාව)", "ගමාල් අබ්දුල් නසාර් (ඊජිප්තුව)", "සුකර්ණෝ (ඉන්දුනීසියාව) සහ ක්වාමේ නක්‍රුමා (ඝානාව)", "නේරු, නසාර්, ටිටෝ, සුකර්ණෝ හා නක්‍රුමා නොබැඳි ව්‍යාපාරයේ පුරෝගාමී නායකයන් පස්දෙනාය."),
    q("1976 වර්ෂයේදී ශ්‍රී ලංකාවේදී පැවැති 5 වන නොබැඳි රාජ්‍ය නායක සමුළුවේ සත්කාරකත්වය හා සභාපතිත්වය දැරුවේ කවුද?", "සිරිමාවෝ බණ්ඩාරනායක මැතිනිය", "ඩී.ඇස්. සේනානායක මහතා", "ඩඩ්ලි සේනානායක මහතා", "ජේ.ආර්. ජයවර්ධන මහතා", "ලොව ප්‍රථම අග්‍රාමාත්‍යවරිය වූ සිරිමාවෝ බණ්ඩාරනායක මැතිනිය 1976 කොළඹ සමුළුව සාර්ථකව මෙහෙයවූවාය."),
    q("1971 එක්සත් ජාතීන්ගේ මහා මණ්ඩලය වෙත 'ඉන්දියන් සාගරය සාම කලාපයක්' (Indian Ocean as a Zone of Peace) කිරීමේ යෝජනාව ඉදිරිපත් කළේ කුමන රටද?", "ශ්‍රී ලංකාව", "ප්‍රංශය", "ජපානය", "බ්‍රසීලය", "මහා බලවතුන්ගේ යුද නැව් හා න්‍යෂ්ටික අවි තරගයෙන් ඉන්දියන් සාගරය නිදහස් කිරීමට ශ්‍රී ලංකාව මෙම යෝජනාව ගෙන ආවේය."),
    q("රටවල් අතර සාමකාමී සහජීවනය සඳහා 1954 දී ඉන්දියාව සහ චීනය අතර ඇති කරගත් 'පංචශීල ප්‍රතිපත්ති' (Panchsheel) මඟින් අවධාරණය කෙරෙන්නේ කුමක්ද?", "භෞමික අඛණ්ඩතාවට ගරු කිරීම, ආක්‍රමණ නොකිරීම, අභ්‍යන්තර කටයුතුවලට ඇඟිලි නොගැසීම හා සමානාත්මතාව", "වෙළඳ බදු දස ගුණයකින් වැඩි කිරීම", "වෙනත් රටවල් යටත් කර ගැනීම", "න්‍යෂ්ටික අවි නිපදවීම", "පසුව බැංඩුං හා නොබැඳි ව්‍යාපාරයේ මූලධර්ම බවට පත් වූයේද පංචශීල ප්‍රතිපත්ති පහයි."),
    q("රටවල් දෙකක් අතර පමණක් සෘජුව ඇති කර ගන්නා ආර්ථික, සංස්කෘතික හෝ ආරක්ෂක සබඳතා හඳුන්වන්නේ කුමන නමින්ද?", "ද්විපාර්ශ්වික සබඳතා (Bilateral Relations)", "බහුපාර්ශ්වික සබඳතා (Multilateral Relations)", "පළාත් පාලන සබඳතා", "අභ්‍යන්තර පක්ෂ සබඳතා", "උදාහරණයක් ලෙස ශ්‍රී ලංකාව සහ ඉන්දියාව අතර අත්සන් කරන වෙළඳ ගිවිසුම ද්විපාර්ශ්වික සබඳතාවකි."),
    q("එක්සත් ජාතීන්ගේ සංවිධානය හෝ සාර්ක් වැනි ආයතන හරහා රටවල් රැසක් එක්ව කටයුතු කිරීම හඳුන්වන්නේ කුමන නමින්ද?", "බහුපාර්ශ්වික සබඳතා (Multilateral Relations)", "ද්විපාර්ශ්වික සබඳතා", "ඒකපාර්ශ්වික තීරණ", "ප්‍රාදේශීය සභා රැස්වීම්", "ගෝලීය දේශගුණික විපර්යාස, වසංගත හා සාගර ආරක්ෂාව වැනි ගැටලු විසඳීමට බහුපාර්ශ්වික සබඳතා අත්‍යවශ්‍යය."),
    q("1951 සැන් ෆ්‍රැන්සිස්කෝ සාම සමුළුවේදී ජපානයෙන් යුද වන්දි නොඉල්ලා මෛත්‍රියෙන් කටයුතු කළ ශ්‍රී ලංකා නියෝජිතයා කවුද?", "ජේ.ආර්. ජයවර්ධන මහතා", "එස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා", "ඩී.බී. ජයතිලක මහතා", "සී.ඩබ්ලිව්.ඩබ්ලිව්. කන්නන්ගර මහතා", "බුදුරජාණන් වහන්සේගේ 'නහී වේරේන වේරානි' දේශනාව උපුටා දක්වමින් කළ කතාව නිසා ශ්‍රී ලංකාවට ජපානයේ දිගුකාලීන මිත්‍රත්වය හිමි විය."),
    q("1952 දී ශ්‍රී ලංකාව විසින් 'රබර්-සහල් ගිවිසුම' (Rubber-Rice Pact) අත්සන් කළේ කුමන රට සමඟද?", "මහජන චීන සමූහාණ්ඩුව", "සෝවියට් රුසියාව", "එක්සත් ජනපදය", "ප්‍රංශය", "රටේ ආහාර හිඟය විසඳීමට හා රබර්වලට සාධාරණ මිලක් ගැනීමට ශ්‍රී ලංකාව අනුගමනය කළ ස්වාධීන ආර්ථික රාජ්‍යතාන්ත්‍රිකත්වයට මෙය නිදසුනකි."),
    q("ලෝකයේ රටවල් අතර ආර්ථික, තාක්ෂණික, සංස්කෘතික හා තොරතුරු අන්තර් සබඳතා ශීඝ්‍රයෙන් බද්ධ වීමේ ක්‍රියාවලිය කුමක්ද?", "ගෝලීයකරණය (Globalization)", "ප්‍රාදේශීයකරණය", "ඒකාධිකාරවාදය", "හුදෙකලාවාදය", "ප්‍රවාහන හා සන්නිවේදන තාක්ෂණයේ දියුණුව නිසා මුළු ලෝකයම 'විශ්ව ගම්මානයක්' (Global Village) බවට පත්ව ඇත."),
    q("ගෝලීයකරණය නිසා ශ්‍රී ලංකාව වැනි සංවර්ධනය වෙමින් පවතින රටවලට හිමිවන ප්‍රධාන ධනාත්මක අවස්ථාවක් කුමක්ද?", "නවීන තාක්ෂණය, අධ්‍යාපන දැනුම, ජාත්‍යන්තර වෙළඳපොළ හා විදේශ ආයෝජනවලට ඉක්මන් ප්‍රවේශය", "දේශීය කර්මාන්ත සියල්ල වැසී යාම", "අන්තර්ජාල සබඳතා බිඳ වැටීම", "විදේශීය සංචාරකයන් නතර වීම", "තොරතුරු තාක්ෂණ සේවා අපනයනය හා ජාත්‍යන්තර ශිෂ්‍යත්ව මඟින් තරුණයන්ට පුළුල් අවස්ථා ලැබේ."),
    q("ගෝලීයකරණයේදී සංවර්ධනය වෙමින් පවතින රටවලට මුහුණ දීමට සිදුවන ප්‍රධාන අභියෝගයක් හෝ අවාසියක් කුමක්ද?", "බහුජාතික සමාගම් හමුවේ දේශීය සුළු කර්මාන්ත බිඳ වැටීම, සංස්කෘතික අනන්‍යතාවට හානි වීම හා දක්ෂයන් රට හැර යාම", "ලෝක තොරතුරු ඉක්මනින් ලැබීම", "ජාත්‍යන්තර වෙළඳාම වැඩි වීම", "වෛද්‍ය තාක්ෂණය දියුණු වීම", "ගෝලීයකරණයේ යහපත් දේ ලබාගන්නා අතරම දේශීය ආර්ථිකය හා සංස්කෘතිය රැකගැනීම රජයේ වගකීමකි."),
    q("ශ්‍රී ලංකාවේ විදේශ සේවයේ නියුතු තානාපති කාර්යාල වර්තමානයේදී ප්‍රමුඛත්වය දෙන 'ආර්ථික රාජ්‍යතාන්ත්‍රිකභාවය' (Economic Diplomacy) යනු කුමක්ද?", "විදේශ ආයෝජන, සංචාරකයන් හා ශ්‍රී ලාංකික අපනයන සඳහා නව වෙළඳපොළවල් දිනා ගැනීමට කටයුතු කිරීම", "විදේශිකයන්ට රේගු බදු නොගෙවා භාණ්ඩ දීම", "දේශීය තේ වගාව නැවැත්වීම", "තානාපති කාර්යාල වසා දැමීම", "රටේ ආර්ථික පුනර්ජීවනය උදෙසා විදේශ සබඳතා උපයෝගී කර ගැනීම ආර්ථික රාජ්‍යතාන්ත්‍රිකත්වයයි."),
    q("රටවල් අතර සුහදතාව ගොඩනැගීම සඳහා කලාව, ක්‍රීඩාව, සංගීතය, සාහිත්‍යය හා ශිෂ්‍ය හුවමාරු යොදාගැනීම කුමන ප්‍රවේශයද?", "සංස්කෘතික රාජ්‍යතාන්ත්‍රිකභාවය හෙවත් මෘදු බලය (Cultural Diplomacy / Soft Power)", "මිලිටරි බලපෑම", "ආර්ථික සම්බාධක", "වීසා තහනම", "ක්‍රිකට් තරග, බෞද්ධ සංස්කෘතික ප්‍රදර්ශන හා අධ්‍යාපන හුවමාරු රටවල් අතර මිත්‍රත්වය වැඩි කරයි."),
    q("විදේශ රටවල සේවය කරන ශ්‍රී ලාංකික ශ්‍රමිකයන් හා ඩයස්පෝරාව (Diaspora) මව්රටේ ආර්ථිකයට දායක වන ප්‍රධාන මාර්ගය කුමක්ද?", "නීත්‍යානුකූල බැංකු ක්‍රම හරහා විදේශ විනිමය ප්‍රේෂණ (Remittances) එවීම හා ආයෝජන සිදු කිරීම", "අපනයන නැවැත්වීම", "විදේශ ගමන් බලපත්‍ර ඉරා දැමීම", "සංචාරකයන් වැළැක්වීම", "විදේශගත ශ්‍රී ලාංකිකයන්ගේ ප්‍රේෂණ රටේ විදේශ සංචිත ශක්තිමත් කිරීමට විශාල ශක්තියක් වේ."),
    q("අනෙක් රටවල අභ්‍යන්තර පාලනයට ඇඟිලි නොගසා තම ස්වාධීනත්වය රැකගැනීම 'විදේශ ප්‍රතිපත්තියේදී' වැදගත් වන්නේ ඇයි?", "රටේ ස්වෛරීභාවය ආරක්ෂා කරගනිමින් කලාපීය සාමය හා අන්‍යෝන්‍ය ගරුත්වය පවත්වාගැනීමට", "ජාත්‍යන්තර ගුවන් ගමන් නැවැත්වීමට", "එක්සත් ජාතීන්ගෙන් ඉවත් වීමට", "ආනයන සියල්ල නැවැත්වීමට", "සියලු රාජ්‍යයන් ප්‍රමාණයෙන් කුඩා වුවද ජාත්‍යන්තර නීතිය ඉදිරියේ ස්වෛරී සමානාත්මතාවයෙන් යුක්තය."),
    q("විදේශ කටයුතු අමාත්‍යාංශය විසින් සකසන ද්විපාර්ශ්වික ගිවිසුමකට 'අවබෝධතා ගිවිසුමක්' (MoU) හා 'බැඳීම් සහිත ගිවිසුමක්' (Treaty) අතර වෙනස කුමක්ද?", "MoU එකක් සහයෝගීතා අභිප්‍රාය දක්වන අතර Treaty එකක් ජාත්‍යන්තර නීතියෙන් දැඩි ලෙස බැඳීම් ඇති කරයි", "දෙකම පළාත් පාලන බදු වේ", "Treaty එකක් කිසිදු රටක් අත්සන් නොකරයි", "MoU එකක් සමථ මණ්ඩලයේ පමණක් භාවිත වේ", "ජාත්‍යන්තර ගිවිසුම් අත්සන් කිරීමේදී ජාතික නීතිය හා පාර්ලිමේන්තු අනුමැතිය පිළිබඳව සැලකිලිමත් වේ."),
    q("ශ්‍රී ලංකාවේ 'විදේශ ගමන් බලපත්‍ර' (Passports) නිකුත් කිරීම හා විදේශිකයන්ට වීසා ලබාදීම සිදු කරන දෙපාර්තමේන්තුව කුමක්ද?", "ආගමන හා විගමන දෙපාර්තමේන්තුව", "විගණකාධිපති දෙපාර්තමේන්තුව", "පුරාවිද්‍යා දෙපාර්තමේන්තුව", "රේගු දෙපාර්තමේන්තුව", "දේශසීමා පාලනය හා පුරවැසියන්ගේ විදේශ ගමන් ලේඛන කළමනාකරණය මෙම දෙපාර්තමේන්තුව මඟින් කෙරේ."),
    q("බහුජාතික සමාගම් (Multinational Corporations - MNCs) ගෝලීය ආර්ථිකය තුළ ක්‍රියාත්මක වන ආකාරය කුමක්ද?", "මව් රටට අමතරව ලෝකයේ රටවල් කිහිපයක භාණ්ඩ නිෂ්පාදනය, සේවා හා අලෙවිය සිදු කිරීම", "එක් ග්‍රාම නිලධාරී වසමකට පමණක් සීමා වීම", "රාජ්‍ය හමුදා පාලනය කිරීම", "ඡන්ද පත්‍රිකා මුද්‍රණය කිරීම", "විදේශ සෘජු ආයෝජන ගෙන එන අතරම දේශීය කම්කරු හා පරිසර නීතිවලට ඔවුන් යටත් විය යුතුය."),
    q("ජාත්‍යන්තර වෙළඳාමේදී රටක් තම දේශීය කර්මාන්ත ආරක්ෂා කර ගැනීමට විදේශීය භාණ්ඩ මත පනවන විශේෂ බදු හඳුන්වන්නේ කුමන නමින්ද?", "රේගු තීරු බදු (Tariffs) සහ ආනයන සීමා (Quotas)", "වරිපනම් බදු", "ප්‍රසාද දීමනා", "පාරිතෝෂික ගෙවීම්", "නිදහස් වෙළඳාම හා ආරක්ෂණවාදය අතර නිවැරදි සමතුලිතතාව පවත්වා ගැනීම රටක ආර්ථික ප්‍රතිපත්තියයි."),
    q("රාජ්‍යතාන්ත්‍රික සබඳතා බිඳ වැටුණු අවස්ථාවකදී රටවල් දෙකක් සාමාන්‍යයෙන් අවසන් විසඳුමට පෙර අනුගමනය කරන රාජ්‍යතාන්ත්‍රික පියවර කුමක්ද?", "තානාපතිවරයා කැඳවා කරුණු විමසීම හෝ උපදේශන සඳහා ආපසු කැඳවීම", "වහාම න්‍යෂ්ටික ප්‍රහාර එල්ල කිරීම", "මුහුදු සීමා සම්පූර්ණයෙන් වැසීම", "එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය ඉරා දැමීම", "රාජ්‍යතාන්ත්‍රික විරෝධතා සටහන් (Diplomatic Notes) හා සංවාද මඟින් ගැටුම් සමනය කර ගැනීම සාමාන්‍ය පිළිවෙතයි."),
    q("ශ්‍රී ලංකාව 'ද්විපුරවැසිභාවය' (Dual Citizenship) ලබාදීමේදී බලාපොරොත්තු වන ප්‍රධාන ජාතික ප්‍රතිලාභය කුමක්ද?", "විදේශ පුරවැසිභාවය ගත් ශ්‍රී ලාංකිකයන්ගේ දැනුම, ආයෝජන හා බැඳීම් රට සමඟ අඛණ්ඩව රඳවා ගැනීම", "පාර්ලිමේන්තු මැතිවරණ නැවැත්වීම", "බදු ආදායම අඩු කිරීම", "පළාත් සභා වසා දැමීම", "ආගමන විගමන පනත යටතේ නියමිත සුදුසුකම් සපුරන විදෙස්ගත ශ්‍රී ලාංකිකයන්ට මෙම අවස්ථාව සලසා ඇත."),
    q("විදේශ ප්‍රතිපත්තිය සාර්ථක වීම සඳහා රටක් තුළ පැවතිය යුතු අභ්‍යන්තර පදනම කුමක්ද?", "රටේ දේශපාලන ස්ථාවරත්වය, ජාතික සමගිය, ආර්ථික ශක්තිය හා යහපාලනය", "නිරන්තර අභ්‍යන්තර යුද ගැටුම්", "මාධ්‍ය වාරණය", "ආර්ථික බංකොලොත්භාවය", "ශක්තිමත් අභ්‍යන්තර පාලනයක් ඇති රටකට ජාත්‍යන්තර තලයේදී වැඩි ගෞරවයක් හා හඬක් හිමිවේ."),
    q("නොබැඳි ව්‍යාපාරය වර්තමානයේ සීතල යුද්ධය අවසන් වූ පසුවත් ක්‍රියාත්මක වන්නේ කුමන අරමුණු වෙනුවෙන්ද?", "සංවර්ධනය වෙමින් පවතින රටවල ආර්ථික සාධාරණත්වය, ත්‍රස්තවාදය පිටුදැකීම හා ස්වෛරීභාවය රැකීම", "නව යුද කඳවුරු ඇති කිරීම", "සාගර පරිසරය දූෂණය කිරීම", "වෙළඳාම තහනම් කිරීම", "ගෝලීය දකුණේ (Global South) රටවල පොදු හඬ නියෝජනය කිරීමට NAM අදටත් ක්‍රියා කරයි."),
    q("රටක ස්වාධීන විදේශ ප්‍රතිපත්තියක් පවත්වාගැනීමට නම් රටේ 'ආර්ථික ස්වාධීනත්වය' වැදගත් වන්නේ ඇයි?", "අධික විදේශ ණය මත යැපෙන විට බලවත් රටවල දේශපාලන බලපෑම්වලට යටත් වීමට සිදුවන බැවිනි", "විදේශ ආයෝජන තහනම් කිරීමට", "අපනයන බින්දුවට දැමීමට", "විදේශ ගමන් බලපත්‍ර අහෝසි කිරීමට", "ශක්තිමත් ජාතික ආර්ථිකයක් විදේශ සබඳතාවලදී ස්වාධීනව හා ගෞරවයෙන් තීරණ ගැනීමට බලය සපයයි."),
    q("ශ්‍රී ලංකාව විදේශ රටවල් සමඟ 'සාගර කලාපීය ආරක්ෂාව' (Maritime Security) පිළිබඳව සහයෝගයෙන් ක්‍රියා කරන්නේ ඇයි?", "මත්ද්‍රව්‍ය ජාවාරම්, මිනිස් ජාවාරම්, නීති විරෝධී මසුන් ඇල්ලීම හා සාගර දූෂණය වැළැක්වීමට", "නැව් ගමනාගමනය නැවැත්වීමට", "ධීවර කර්මාන්තය තහනම් කිරීමට", "වරායවල් වසා දැමීමට", "දූපත් රාජ්‍යයක් ලෙස අන්තර්ජාතික මුහුදු මාර්ග ආරක්ෂා කිරීම ශ්‍රී ලංකාවේ හා කලාපයේ යහපතට හේතු වේ."),
    q("විදේශ රටකදී ශ්‍රී ලාංකික පුරවැසියෙකු හදිසි ආපදාවකට හෝ නීතිමය ගැටලුවකට මුහුණ දුන් විට පළමුව සම්බන්ධ විය යුත්තේ කා සමඟද?", "එරට පිහිටි ශ්‍රී ලංකා තානාපති කාර්යාලය හෝ මහ කොමසාරිස් කාර්යාලය", "ප්‍රාදේශීය සභා සභාපතිවරයා", "පළාත් පාලන කොමසාරිස්", "සමථ මණ්ඩල සභාපති", "විදේශගත පුරවැසියන්ට කොන්සියුලර් සහය, හදිසි ගමන් ලේඛන හා ආරක්ෂාව සැලසීම තානාපති කාර්යාල වගකීමකි."),
    q("රටවල් අතර සිදුවන 'නිදහස් වෙළඳ ගිවිසුමක්' (Free Trade Agreement - FTA) මඟින් ප්‍රධාන වශයෙන් අදහස් කරන්නේ කුමක්ද?", "සාමාජික රටවල් අතර තීරු බදු හා වෙළඳ බාධක අඩු කර භාණ්ඩ හා සේවා හුවමාරුව පහසු කිරීම", "සියලුම වෙළඳාම තහනම් කිරීම", "රේගු බදු දස ගුණයකින් වැඩි කිරීම", "මුදල් භාවිතය නැවැත්වීම", "දේශීය කර්මාන්තවලට හානි නොවන සේ නිවැරදි ආරක්ෂණ විධිවිධාන සහිතව වෙළඳ ගිවිසුම් ඇති කරගත යුතුය."),
    q("1960 වර්ෂයේදී ලොව ප්‍රථම කාන්තා අග්‍රාමාත්‍යවරිය ලෙස පත් වූ සිරිමාවෝ බණ්ඩාරනායක මැතිනිය ශ්‍රී ලංකාවට ජාත්‍යන්තර කීර්තියක් ගෙන ආ විදේශ ප්‍රතිපත්ති ජයග්‍රහණයක් කුමක්ද?", "1974-1976 කාලයේ ඉන්දියාව සමඟ සාකච්ඡාවෙන් කච්චතිව් දූපතේ ස්වෛරී අයිතිය තහවුරු කිරීම හා 1976 NAM සමුළුව පැවැත්වීම", "බ්‍රිතාන්‍ය යටත්විජිත පාලනය යළි ඇරඹීම", "එක්සත් ජාතීන්ගෙන් ඉවත් වීම", "රබර්-සහල් ගිවිසුම අවලංගු කිරීම", "සාමකාමී රාජ්‍යතාන්ත්‍රික සාකච්ඡා මඟින් දේශසීමා හා පුරවැසි ගැටලු විසඳා ගැනීමට ඇය සමත් වූවාය."),
    q("සංස්කෘතික ගෝලීයකරණය හමුවේ ලොව සියලු රටවල් එකම ආහාර, ඇඳුම් හා ජීවන රටාවකට හුරුවීමෙන් ඇති වන අවදානම කුමක්ද?", "දේශීය භාෂා, සාම්ප්‍රදායික කලා ශිල්ප හා සංස්කෘතික විවිධත්වය ක්‍රමයෙන් වඳ වී යාම", "ජනගහනය සීඝ්‍රයෙන් වැඩි වීම", "ගුවන් ගමන් නතර වීම", "සාක්ෂරතාව ශුන්‍ය වීම", "තම මව් භාෂාව, ජන කලා හා යහපත් සම්ප්‍රදායන් රැකගනිමින් නවීන ලෝකය සමඟ එක්වීම සුදුසුය."),
    q("ශ්‍රී ලංකාව 1948 දී නිදහස ලැබීමෙන් පසු 1955 දෙසැම්බර් 14 දින සාමාජිකත්වය ලබාගත් ප්‍රධානතම විශ්ව සංවිධානය කුමක්ද?", "එක්සත් ජාතීන්ගේ සංවිධානය (UNO)", "නේටෝ යුද සන්ධානය", "යුරෝපා සංගමය", "අප්‍රිකානු සංගමය", "එවකට පැවති සීතල යුද නිෂේධ බල ප්‍රශ්න විසඳුණු පසු 1955 දී ශ්‍රී ලංකාව එක්සත් ජාතීන්ගේ සාමාජිකයෙකු විය."),
    q("රටක 'මහජන රාජ්‍යතාන්ත්‍රිකභාවය' (Public Diplomacy) ශක්තිමත් කිරීම සඳහා වැදගත් වන සාධකය කුමක්ද?", "විදේශීය ජනතාව අතර රට පිළිබඳ ධනාත්මක ප්‍රතිරූපයක් ගොඩනගන සංචාරක සත්කාරකත්වය, මාධ්‍ය හා සංස්කෘතිය", "සංචාරකයන්ට රට තහනම් කිරීම", "තානාපති කාර්යාල වසා දැමීම", "අන්තර්ජාලය අවහිර කිරීම", "රාජ්‍යයන් අතර පමණක් නොව රටවල ජනතාව අතර මිත්‍රත්වය ගොඩනැගීම සංචාරක හා වෙළඳ ක්ෂේත්‍ර දියුණු කරයි."),
    q("ගෝලීය අර්බුද හමුවේ වසංගත, ආහාර හිඟය හා දේශගුණ විපර්යාස වැනි අභියෝග ජය ගැනීමට ශ්‍රී ලංකාව අනුගමනය කළ යුතු ඥානාන්විත විදේශ ප්‍රතිපත්තිය කුමක්ද?", "කිසිදු බලවතෙකුට සතුරු නොවී සියලු මිත්‍ර රටවල් හා ජාත්‍යන්තර ආයතන සමඟ සමබරව කටයුතු කිරීම", "සියලු තානාපති සබඳතා කපා හැරීම", "එක් රටක් සමඟ පමණක් ගනුදෙනු කිරීම", "ජාත්‍යන්තර නීති ප්‍රතික්ෂේප කිරීම", "සමබර හා ප්‍රායෝගික මිත්‍රශීලී විදේශ ප්‍රතිපත්තිය කුඩා රටක ස්ථාවරත්වය ආරක්ෂා කරයි."),
    q("නව තානාපතිවරයෙකු සත්කාරක රටක නිල වශයෙන් වැඩ භාර ගැනීමට පෙර එරට රාජ්‍ය නායකයා වෙත පිළිගන්වන නිල ලියවිල්ල කුමක්ද?", "අක්තපත්‍ර (Letters of Credence)", "ප්‍රතිපත්ති ප්‍රකාශනය", "රේගු බලපත්‍රය", "ගමන් බලපත්‍ර අංකය", "රාජ්‍ය නායකයා විසින් තම නියෝජිතයා හඳුන්වා දෙමින් අක්තපත්‍ර නිකුත් කරනු ලැබේ."),
    q("සත්කාරක රාජ්‍යයක් විසින් යම් විදේශීය රාජ්‍යතාන්ත්‍රිකයෙකු රටින් පිටුවහල් කිරීමට පෙර ප්‍රකාශ කරන තත්ත්වය කුමක්ද?", "පර්සෝනා නොන් ග්‍රාටා (නොපිළිගත් පුද්ගලයෙකු)", "රාජ්‍ය අමුත්තා", "මහ කොමසාරිස්", "සම්මානනීය පුරවැසියා", "රාජ්‍යතාන්ත්‍රික සබඳතා පිළිබඳ වියානා සම්මුතියේ 9 වන වගන්තිය අනුව මෙය සිදු කෙරේ."),
    q("1950 දී කොළඹ පැවති පොදුරාජ්‍ය මණ්ඩලීය විදේශ අමාත්‍ය සමුළුවේ ප්‍රතිඵලයක් ලෙස ආසියා පැසිෆික් සංවර්ධනය සඳහා බිහි වූ සැලැස්ම කුමක්ද?", "කොළඹ ක්‍රමය (Colombo Plan)", "මාර්ෂල් සැලැස්ම", "බැංඩුං සැලැස්ම", "ඩොනමෝර් සැලැස්ම", "ජේ.ආර්. ජයවර්ධන හා පර්සි ස්පෙන්ඩර් යන මහත්වරුන්ගේ යෝජනාවෙන් කොළඹ ක්‍රමය 1951 දී ක්‍රියාත්මක විය."),
    q("කොළඹ ක්‍රමයේ මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "කොළඹ", "නවදිල්ලිය", "ලන්ඩන්", "කැන්බරා", "මානව සම්පත් සංවර්ධනය හා තාක්ෂණික සහයෝගීතාව වෙනුවෙන් කොළඹ ක්‍රමය ක්‍රියාත්මක වේ."),
    q("1957 දී කටුනායක ගුවන් හමුදා කඳවුර සහ ත්‍රිකුණාමලය නාවික කඳවුර බ්‍රිතාන්‍ය පාලනයෙන් නිදහස් කර ගැනීමට මූලික වූ අග්‍රාමාත්‍යවරයා කවුද?", "එස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා", "ඩී.ඇස්. සේනානායක මහතා", "සර් ජෝන් කොතලාවල මහතා", "ඩඩ්ලි සේනානායක මහතා", "බ්‍රිතාන්‍ය හමුදා කඳවුරු ඉවත් කිරීම ශ්‍රී ලංකාව සැබෑ නොබැඳි ප්‍රතිපත්තියකට පිවිසීම සනිටුහන් කළේය."),
    q("1956 න් පසු ශ්‍රී ලංකාව සෝවියට් සංගමය හා චීනය ඇතුළු සමාජවාදී රටවල් සමඟ තානාපති සබඳතා ආරම්භ කිරීමට හේතු වූ ප්‍රතිපත්තිය කුමක්ද?", "ගතික මධ්‍යස්ථ හා නොබැඳි විදේශ ප්‍රතිපත්තිය", "බටහිර පක්ෂපාතී ප්‍රතිපත්තිය", "යුද කඳවුරු බැඳීමේ ප්‍රතිපත්තිය", "රාජ්‍ය හුදෙකලා ප්‍රතිපත්තිය", "ලෝකයේ සියලු දේශපාලන කඳවුරු සමඟ මිත්‍රශීලී රාජ්‍යතාන්ත්‍රික සබඳතා ගොඩනගා ගැනීම මෙහි අරමුණ විය."),
    q("1964 දී ශ්‍රී ලංකාවේ හා ඉන්දියාවේ අගමැතිවරුන් අතර අත්සන් කළ සිරිමා-ශාස්ත්‍රී ගිවිසුම විසඳීමට අරමුණු කළ ගැටලුව කුමක්ද?", "රාජ්‍ය අහිමි ඉන්දියානු සම්භවයක් ඇති වතු කම්කරුවන්ගේ පුරවැසිභාවය", "කච්චතිව් දූපතේ තෙල් කැණීම්", "ගුවන් තොටුපළ බදු ගාස්තු", "තේ අපනයන කෝටාව", "සිරිමාවෝ බණ්ඩාරනායක මැතිනිය හා ලාල් බහදූර් ශාස්ත්‍රී මහතා අතර 1964 ඔක්තෝබර් 30 දින මෙය අත්සන් කෙරිණි."),
    q("1974 දී ශ්‍රී ලංකාව සහ ඉන්දියාව අතර සමුද්‍රීය දේශසීමාව නිරවුල් කර ගනිමින් ශ්‍රී ලංකාවට අයිතිය තහවුරු කළ දූපත කුමක්ද?", "කච්චතිව් දූපත", "මන්නාරම් දූපත", "ඩෙල්ෆ්ට් දූපත", "කරෙයිනගර් දූපත", "1974 පෝක් සමුද්‍ර සන්ධි සමුද්‍රීය සීමා ගිවිසුම මඟින් කච්චතිව් දූපතේ අයිතිය නිරවුල් කෙරිණි."),
    q("රාජ්‍යයන් අතර මුහුදු සීමා, ආර්ථික කලාප හා සමුද්‍ර සම්පත් පාලනය නියාමනය කරන 1982 එක්සත් ජාතීන්ගේ සම්මුතිය කුමක්ද?", "එක්සත් ජාතීන්ගේ සමුද්‍ර නීති සම්මුතිය (UNCLOS)", "චිකාගෝ ගුවන් සේවා සම්මුතිය", "බර්න් ප්‍රකාශන හිමිකම් සම්මුතිය", "ජිනීවා කම්කරු සම්මුතිය", "UNCLOS අනුව වෙරළබඩ රාජ්‍යයකට නාවික සැතපුම් 12ක භෞමික මුහුදක් හා සැතපුම් 200ක ආර්ථික කලාපයක් හිමිවේ."),
    q("දූපත් රාජ්‍යයක වෙරළ තීරයේ සිට නාවික සැතපුම් 200ක් දක්වා විහිදෙන සාගර සම්පත් භුක්ති විඳීමට ඇති කලාපය හඳුන්වන්නේ කෙසේද?", "අනන්‍ය ආර්ථික කලාපය (EEZ)", "ජාත්‍යන්තර ගුවන් කලාපය", "නිදහස් වෙළඳ කලාපය", "පළාත් පාලන කලාපය", "මසුන් ඇල්ලීම හා මුහුදු පතුලේ ඛනිජ සම්පත් ගවේෂණය සඳහා මෙම කලාපයේ අයිතිය රාජ්‍යයට හිමිවේ."),
    q("රටක විදේශ ප්‍රතිපත්තිය සකස් කිරීමේදී හා ක්‍රියාත්මක කිරීමේදී වගකිව යුතු ප්‍රධාන රාජ්‍ය ආයතනය කුමක්ද?", "විදේශ කටයුතු අමාත්‍යාංශය", "අධ්‍යාපන අමාත්‍යාංශය", "කෘෂිකර්ම දෙපාර්තමේන්තුව", "මැතිවරණ කොමිෂන් සභාව", "ජනාධිපතිවරයාගේ හා අමාත්‍ය මණ්ඩලයේ ප්‍රතිපත්ති මත විදේශ කටයුතු අමාත්‍යාංශය රාජ්‍යතාන්ත්‍රික සේවා මෙහෙයවයි."),
    q("විදේශ රටක සිටින තානාපති කාර්යාල පරිශ්‍රය හා රාජ්‍යතාන්ත්‍රික නිලධාරීන් අනවසරයෙන් අත්අඩංගුවට ගැනීමෙන් වළක්වන නීතිමය රැකවරණය කුමක්ද?", "රාජ්‍යතාන්ත්‍රික මුක්තිය (Diplomatic Immunity)", "පාර්ලිමේන්තු වරප්‍රසාදය", "සමථ මණ්ඩල බලය", "විධායක සමාව", "සත්කාරක රටේ දේශපාලන බලපෑම්වලින් තොරව තානාපතිවරුන්ට රාජකාරි කිරීමට මෙය අත්‍යවශ්‍ය වේ."),
    q("තමන් සේවය කරන සත්කාරක රටෙහි රාජ්‍යතාන්ත්‍රික මුක්තිය හිමි නියෝජිතයෙකු සිදු කළ යුතු මූලික යුතුකමක් කුමක්ද?", "සත්කාරක රටේ නීතිවලට ගරු කිරීම හා එරට අභ්‍යන්තර දේශපාලනයට මැදිහත් නොවීම", "සත්කාරක රටේ මැතිවරණවලට තරග කිරීම", "විරුද්ධ පක්ෂවලට අරමුදල් සැපයීම", "බදු නීති උල්ලංඝනය කිරීම", "වියානා සම්මුතියේ 41 වන වගන්තිය අනුව අභ්‍යන්තර කටයුතුවලට මැදිහත් නොවීම තානාපතිවරුන්ගේ වගකීමකි."),
    q("ප්‍රධාන තානාපති කාර්යාලයකට අමතරව විදේශීය වාණිජ නගරයක විවෘත කරන පුරවැසි හා වෙළඳ සේවා කාර්යාලය කුමක්ද?", "කොන්සල් ජනරාල් කාර්යාලය", "අගවිනිසුරු කාර්යාලය", "පළාත් සභා කාර්යාලය", "ප්‍රාදේශීය ලේකම් කාර්යාලය", "උදාහරණ ලෙස ජෙඩා, ඩුබායි, ටොරොන්ටෝ හෝ මුම්බායි වැනි නගරවල ශ්‍රී ලංකා කොන්සල් කාර්යාල පවතී."),
    q("විදේශ රටක වාසය කරන ශ්‍රී ලාංකිකයන් අතර ජාතික උරුමය, භාෂාව හා මව්රට පිළිබඳ බැඳීම පවත්වා ගැනීමට තානාපති කාර්යාල ඉටු කරන කාර්යයක් කුමක්ද?", "ජාතික හා සංස්කෘතික උත්සව සංවිධානය කිරීම සහ පුරවැසි සේවා සැපයීම", "විදේශීය බැංකු වසා දැමීම", "දේශීය පළාත් පාලන බදු එකතු කිරීම", "පුරවැසිභාවය බලෙන් අහෝසි කිරීම", "විදේශගත ප්‍රජාව හා මව්රට අතර සබඳතාව ශක්තිමත් කිරීමට තානාපති කාර්යාල ක්‍රියා කරයි."),
    q("රටවල් දෙකක් හෝ කිහිපයක් අතර අත්සන් කරන ජාත්‍යන්තර ගිවිසුමක් පාර්ලිමේන්තුව හෝ ව්‍යවස්ථාදායකය මඟින් නිල වශයෙන් ස්ථිර කිරීම හඳුන්වන්නේ කෙසේද?", "අපරාජිත කිරීම හෙවත් ස්ථිර කිරීම (Ratification)", "විසුරුවා හැරීම", "අත්හිටුවීම", "පිටුවහල් කිරීම", "රාජ්‍යයන් අත්සන් කළ ගිවිසුමකට නීතිමය බලය ලැබීමට අභ්‍යන්තර නීති අනුව ස්ථිර කිරීම අවශ්‍ය වේ."),
    q("රාජ්‍ය නායකයෙකු හෝ විදේශ ඇමතිවරයෙකු තවත් රටක සිදු කරන නිල සංචාර මඟින් ප්‍රධාන වශයෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "ද්විපාර්ශ්වික දේශපාලන, ආර්ථික හා ආරක්ෂක සහයෝගීතාව ඉහළ නැංවීම", "සංචාරක වීසා ක්‍රමය නැවැත්වීම", "අනෙක් රටේ පාර්ලිමේන්තුව විසුරුවා හැරීම", "ගුවන් තොටුපළවල් වසා දැමීම", "ඉහළ පෙළේ රාජ්‍යතාන්ත්‍රික හමු මඟින් අන්‍යෝන්‍ය විශ්වාසය හා වෙළඳ සබඳතා වර්ධනය වේ."),
    q("දේශපාලන අස්ථාවරත්වය හෝ යුද්ධය නිසා වෙනත් රටකට ගොස් ආරක්ෂාව පතන පුද්ගලයෙකුට සත්කාරක රට ලබා දෙන රැකවරණය කුමක්ද?", "දේශපාලන රැකවරණය (Asylum)", "තානාපති මුක්තිය", "රේගු බලපත්‍රය", "ආර්ථික සම්බාධකය", "මානව හිමිකම් පිළිබඳ විශ්ව ප්‍රකාශනයේ 14 වන වගන්තියෙන් රැකවරණය පැතීමේ අයිතිය පිළිගෙන ඇත."),
    q("උසස් අධ්‍යාපනය ලැබූ වෛද්‍යවරුන්, ඉංජිනේරුවන් හා විද්‍යාඥයන් වඩා හොඳ වැටුප් හා පහසුකම් සොයා විදේශගත වීම හඳුන්වන්නේ කුමන ගැටලුව ලෙසද?", "බුද්ධි ගලනය (Brain Drain)", "ප්‍රාග්ධන ගලා ඒම", "තාක්ෂණික හුවමාරුව", "අපනයන විවිධාංගීකරණය", "උගත් වෘත්තිකයන් රට හැර යාම සංවර්ධනය වෙමින් පවතින රටවල සේවා අංශවලට අභියෝගයකි."),
    q("විදේශගත වූ දක්ෂ ශ්‍රී ලාංකික වෘත්තිකයන්ගේ දැනුම හා අත්දැකීම් නැවත මව්රටේ දියුණුවට යොදා ගැනීම හඳුන්වන්නේ කුමන නමින්ද?", "බුද්ධි ප්‍රතිලාභය හෙවත් බුද්ධි සංසරණය (Brain Gain / Brain Circulation)", "ආර්ථික හුදෙකලාවාදය", "වෙළඳ ඒකාධිකාරය", "තීරුබදු ප්‍රතිපත්තිය", "විදේශීය විශේෂඥ දැනුම හා ආයෝජන මව්රටට ගෙන්වා ගැනීමෙන් බුද්ධි ගලනයේ අවාසි අවම කළ හැකිය."),
    q("ශ්‍රී ලංකාවේ විදේශ විනිමය ආදායම වැඩි කර ගැනීම සඳහා 'සංචාරක රාජ්‍යතාන්ත්‍රිකත්වය' වැදගත් වන්නේ ඇයි?", "විදේශීය සංචාරකයන් ආකර්ෂණය වීමෙන් හෝටල්, ප්‍රවාහන හා හස්ත කර්මාන්ත ක්ෂේත්‍රවලට විදේශ විනිමය ලැබෙන බැවිනි", "දේශීය ගුවන් තොටුපළවල් වසා දැමීමට හැකි වන බැවිනි", "වීසා ක්‍රමය සම්පූර්ණයෙන් නැවැත්වීමට", "සංචාරකයන්ට රටට ඇතුළු වීම තහනම් කිරීමට", "ආරක්ෂිත හා මිත්‍රශීලී ජාත්‍යන්තර ප්‍රතිරූපයක් තිබීම සංචාරක කර්මාන්තයේ දියුණුවට සෘජුව බලපායි."),
    q("රටකට පැමිණෙන විදේශීය ආයෝජකයන් විසින් කර්මාන්තශාලා හෝ ව්‍යාපාර ආරම්භ කිරීම හඳුන්වන්නේ කෙසේද?", "විදේශ සෘජු ආයෝජන (Foreign Direct Investment - FDI)", "දේශීය පාරිභෝගික ණය", "වරිපනම් බදු", "මුදල් අච්චු ගැසීම", "FDI මඟින් රැකියා අවස්ථා, නව තාක්ෂණය හා අපනයන ආදායම් රටට හිමිවේ."),
    q("ශ්‍රී ලංකාවට විදේශ සෘජු ආයෝජන ආකර්ෂණය කර ගැනීම සහ අපනයන සැකසුම් කලාප පරිපාලනය කිරීම සිදු කරන රාජ්‍ය ආයතනය කුමක්ද?", "ශ්‍රී ලංකා ආයෝජන මණ්ඩලය (BOI)", "මැතිවරණ කොමිෂන් සභාව", "ජාතික පුස්තකාල සේවා මණ්ඩලය", "මහා භාරකාර දෙපාර්තමේන්තුව", "කටුනායක, බියගම හා කොග්ගල වැනි නිදහස් වෙළඳ කලාප BOI යටතේ ක්‍රියාත්මක වේ."),
    q("ජාත්‍යන්තර වෙළඳාමේදී ශ්‍රී ලංකාව වැනි කුඩා රටක නිෂ්පාදන සඳහා යුරෝපය වැනි කලාපවලින් ලැබෙන විශේෂ බදු සහන ක්‍රමයකට නිදසුනක් කුමක්ද?", "ජී.එස්.පී. ප්ලස් (GSP+) බදු සහනය", "සැෆ්ටා අධිබදු ක්‍රමය", "වරිපනම් සහනය", "කොන්සල් මුක්තිය", "මානව හිමිකම් හා යහපාලන සම්මුති 27ක් ක්‍රියාත්මක කිරීමේ පදනම මත යුරෝපා සංගමය GSP+ සහනය සපයයි."),
    q("රටක විදේශ ප්‍රතිපත්තිය සැකසීමේදී 'භූගෝලීය පිහිටීමට' අමතරව බලපාන ප්‍රධාන ආර්ථික සාධකය කුමක්ද?", "රටේ අපනයන වෙළඳපොළවල්, බලශක්ති අවශ්‍යතා හා සංවර්ධන ප්‍රමුඛතා", "පාසල් නිල ඇඳුම් වර්ණය", "පළාත් සභා මන්ත්‍රී සංඛ්‍යාව", "ග්‍රාම නිලධාරී වසම් ගණන", "තේ, ඇඟලුම්, සංචාරක හා තොරතුරු තාක්ෂණ සේවා අපනයන ආරක්ෂා කිරීම විදේශ ප්‍රතිපත්තියේ ප්‍රධාන අරමුණකි."),
    q("එක් රටක් විසින් තවත් රටක වැරදි ප්‍රතිපත්තිවලට විරෝධය දැක්වීම සඳහා වෙළඳාම හා මූල්‍ය ගනුදෙනු සීමා කිරීමේ පියවර කුමක්ද?", "ආර්ථික සම්බාධක පැනවීම (Economic Sanctions)", "නිදහස් වෙළඳ ගිවිසුම් අත්සන් කිරීම", "තානාපති සබඳතා ශක්තිමත් කිරීම", "සංස්කෘතික හුවමාරු වැඩසටහන්", "ජාත්‍යන්තර සාමයට තර්ජනයක් වන අවස්ථාවලදී එක්සත් ජාතීන්ගේ ආරක්ෂක මණ්ඩලයද සම්බාධක පනවයි."),
    q("ශ්‍රී ලංකාව 1948 නිදහස ලැබීමෙන් පසු ප්‍රථම දශකයේදී විදේශ ප්‍රතිපත්තිය තුළ වැඩි වශයෙන් සමීපව කටයුතු කළේ කුමන කඳවුර සමඟද?", "බ්‍රිතාන්‍යය ප්‍රමුඛ පොදුරාජ්‍ය මණ්ඩලය හා බටහිර රටවල්", "වෝර්සෝ යුද සන්ධානය", "ලතින් ඇමරිකානු සංගමය", "අරාබි සන්ධානය", "1947 ආරක්ෂක ගිවිසුම හා කොළඹ ක්‍රමය යටතේ බ්‍රිතාන්‍යය හා බටහිර රටවල් සමඟ මුල් කාලයේදී සමීප සබඳතා පැවතුණි."),
    q("1956 වසරේදී එස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා අග්‍රාමාත්‍ය වීමෙන් පසු ශ්‍රී ලංකාවේ විදේශ ප්‍රතිපත්තියේ සිදු වූ ප්‍රධාන වෙනස කුමක්ද?", "නොබැඳි මධ්‍යස්ථ ප්‍රතිපත්තියක් අනුගමනය කරමින් සමාජවාදී රටවල් සමඟද තානාපති සබඳතා ඇරඹීම", "පොදුරාජ්‍ය මණ්ඩලයෙන් ඉවත් වී යුද කඳවුරකට එක්වීම", "සියලු තානාපති කාර්යාල වසා දැමීම", "බ්‍රිතාන්‍ය හමුදා කඳවුරු පුළුල් කිරීම", "ලෝකයේ සෑම රටක් සමඟම මිත්‍රශීලී සබඳතා පැවැත්වීමේ ගතික නොබැඳි පිළිවෙත 1956 දී ශක්තිමත් විය."),
    q("රාජ්‍ය නායකයන් අතර වහාම සන්නිවේදනය කිරීමෙන් යුදමය වැරදි වැටහීම් වැළැක්වීමට භාවිත කරන සෘජු දුරකථන සබඳතාව කුමක්ද?", "රතු දුරකථන සබඳතාව (Hotline)", "සාමාන්‍ය රැහැන් තැපෑල", "තානාපති මල්ල", "විශ්ව ගුවන් විදුලිය", "හදිසි ජාත්‍යන්තර අර්බුදවලදී සෘජු රාජ්‍යතාන්ත්‍රික සන්නිවේදනය සාමය රැකීමට උපකාරී වේ."),
    q("තානාපති කාර්යාලය හා මව්රටේ විදේශ කටයුතු අමාත්‍යාංශය අතර රහසිගත නිල ලිපි හුවමාරු කරන ආරක්ෂිත පාර්සලය හඳුන්වන්නේ කෙසේද?", "රාජ්‍යතාන්ත්‍රික මල්ල (Diplomatic Pouch)", "රේගු පෙට්ටිය", "අධිකරණ ලේඛනය", "විදේශ විනිමය කවරය", "1961 වියානා සම්මුතිය අනුව රාජ්‍යතාන්ත්‍රික මල්ල සෝදිසි කිරීම හෝ රඳවා තබා ගැනීම තහනම්ය."),
    q("තම රටේ පුරවැසියන්ට හා විදේශිකයන්ට පරිසර සංරක්ෂණය හා දේශගුණික අරමුදල් දිනා ගැනීමට රටවල් අතර සිදු කරන රාජ්‍යතාන්ත්‍රික සාකච්ඡා මොනවාද?", "දේශගුණික රාජ්‍යතාන්ත්‍රිකභාවය (Climate Diplomacy)", "යුද රාජ්‍යතාන්ත්‍රිකභාවය", "සමුද්‍ර කොල්ලකෑම", "පළාත් සභා සාකච්ඡාව", "පැරිස් දේශගුණ ගිවිසුම වැනි සම්මුති හරහා දේශගුණ යුක්තිය වෙනුවෙන් කුඩා දූපත් රාජ්‍යයන් හඬ නඟයි."),
    q("දේශගුණික විපර්යාස අවම කිරීම සඳහා 2015 දී ලෝකයේ රටවල් බහුතරයක් අත්සන් කළ වැදගත් ජාත්‍යන්තර ගිවිසුම කුමක්ද?", "පැරිස් දේශගුණික ගිවිසුම", "රබර්-සහල් ගිවිසුම", "මාස්ට්‍රිච් ගිවිසුම", "වර්සේල්ස් ගිවිසුම", "ගෝලීය උණුසුම සෙල්සියස් අංශක 1.5 - 2 ට වඩා පහළින් තබා ගැනීම පැරිස් ගිවිසුමේ අරමුණයි."),
    q("වර්තමානයේදී රාජ්‍යතාන්ත්‍රික කටයුතු සඳහා සමාජ මාධ්‍ය, නිල වෙබ් අඩවි හා මාර්ගගත සමුළු යොදා ගැනීම හඳුන්වන්නේ කෙසේද?", "ඩිජිටල් රාජ්‍යතාන්ත්‍රිකභාවය (Digital Diplomacy)", "සාම්ප්‍රදායික තැපැල් සේවය", "මුහුදු ගමන් රාජ්‍යතාන්ත්‍රිකත්වය", "රහසිගත ඔත්තු බැලීම", "විදේශගත පුරවැසියන්ට ඉක්මන් තොරතුරු සැපයීමට හා රටේ ප්‍රතිරූපය ප්‍රචලිත කිරීමට ඩිජිටල් මාධ්‍ය යොදා ගැනේ."),
    q("අසල්වැසි රටවල් සමඟ ධීවර කර්මාන්තයේදී ඇති වන සමුද්‍ර දේශසීමා ගැටලු විසඳා ගැනීමට වඩාත් සුදුසු ක්‍රමය කුමක්ද?", "ද්විපාර්ශ්වික සාකච්ඡා, ඒකාබද්ධ මුර සංචාර හා ජාත්‍යන්තර සමුද්‍ර නීතිය අනුගමනය කිරීම", "ධීවර බෝට්ටුවලට වහාම වෙඩි තැබීම", "ධීවර කර්මාන්තය සම්පූර්ණයෙන් තහනම් කිරීම", "සාගරය දූෂණය කිරීම", "සාමකාමී රාජ්‍යතාන්ත්‍රික සංවාදය ධීවර ප්‍රජාවගේ ජීවනෝපාය හා කලාපීය සුහදතාව ආරක්ෂා කරයි."),
    q("ශ්‍රී ලංකාව සිය විදේශ ප්‍රතිපත්තියේදී 'මිත්‍රශීලී පළමුවැන්න' නැතහොත් 'අසල්වැසියන්ට ප්‍රමුඛත්වය' දීම වැදගත් වන්නේ ඇයි?", "කලාපීය වෙළඳාම, සංචාරක ආගමනය, සාගර ආරක්ෂාව හා හදිසි ආපදා සහන සඳහා අසල්වැසි සහය තීරණාත්මක බැවිනි", "දුරස්ථ රටවල් සමඟ ගනුදෙනු නැවැත්වීමට", "ගුවන් සේවා නැවැත්වීමට", "විදේශීය භාෂා ඉගෙනීම වැළැක්වීමට", "දකුණු ආසියාතික අසල්වැසි රටවල් සමඟ සුහදතාව පවත්වා ගැනීම ශ්‍රී ලංකාවේ ආර්ථික හා ආරක්ෂක හිතසුවට හේතු වේ."),
    q("විදේශ රටකින් ශ්‍රී ලංකාවට ලැබෙන 'නොමිලේ ආධාර' (Grants) සහ 'විදේශ ණය' (Foreign Loans) අතර ප්‍රධාන වෙනස කුමක්ද?", "නොමිලේ ආධාර ආපසු ගෙවිය යුතු නැති අතර විදේශ ණය පොලිය සහිතව නියමිත කාලයේදී ආපසු ගෙවිය යුතුය", "දෙකම කිසිදා ආපසු නොගෙවයි", "ආධාර සඳහා සියයට සියයක් පොලී ගෙවිය යුතුය", "ණය යනු රටේ අභ්‍යන්තර බදු වේ", "විදේශ ණය ඵලදායී ආර්ථික ව්‍යාපෘති සඳහා පමණක් යොදා නොගතහොත් රට ණය අර්බුදයකට ලක් විය හැකිය."),
    q("සංවර්ධනය වෙමින් පවතින රටවල දිළිඳු බව අඩු කිරීම හා මූලික යටිතල පහසුකම් ගොඩනැගීම සඳහා 'ද්විපාර්ශ්වික සංවර්ධන ආධාර' සපයන ආයතනයකට නිදසුනක් කුමක්ද?", "ජපන් ජාත්‍යන්තර සහයෝගීතා ආයතනය (JICA)", "ශ්‍රී ලංකා මැතිවරණ කොමිසම", "කොළඹ මහ නගර සභාව", "ශ්‍රී ලංකා සමථ මණ්ඩල කොමිසම", "විවිධ මිත්‍ර රටවල් තම සංවර්ධන ආයතන හරහා මාර්ග, රෝහල්, ජල යෝජනා ක්‍රම හා අධ්‍යාපනයට සහය දෙයි."),
    q("ගෝලීයකරණය යටතේ 'රාජ්‍ය නොවන ජාත්‍යන්තර සංවිධාන' (INGOs) ඉටු කරන ධනාත්මක කාර්යභාරයක් කුමක්ද?", "ආපදා සහන, මානව හිමිකම් ප්‍රවර්ධනය, සෞඛ්‍ය හා පරිසර සංරක්ෂණ ව්‍යාපෘති ක්‍රියාත්මක කිරීම", "රටක මුදල් අච්චු ගැසීම", "පාර්ලිමේන්තු මැතිවරණ පැවැත්වීම", "රාජ්‍ය හමුදාවලට අණ දීම", "ඔක්ස්ෆෑම් හා සේව් ද චිල්ඩ්‍රන් වැනි ආයතන රජයන් සමඟ සම්බන්ධීකරණයෙන් මානුෂීය සේවා සපයයි."),
    q("එක් රටක පාසල් ශිෂ්‍යයන්ට හෝ විශ්වවිද්‍යාල සිසුන්ට වෙනත් රටවල අධ්‍යාපනය ලැබීමට අවස්ථාව සලසන ජාත්‍යන්තර වැඩසටහන් හඳුන්වන්නේ කෙසේද?", "විදේශ ශිෂ්‍යත්ව හා අධ්‍යාපනික හුවමාරු වැඩසටහන්", "වෙළඳ සම්බාධක වැඩසටහන්", "රේගු තීරු බදු වැඩසටහන්", "යුද පුහුණු වැඩසටහන්", "අධ්‍යාපනික හුවමාරු මඟින් දැනුම හුවමාරුව මෙන්ම තරුණ පරපුර අතර ජාත්‍යන්තර මිත්‍රත්වය ගොඩනැගේ."),
    q("ජාත්‍යන්තර ගුවන් ගමන් හා සාගර නාවික ගමනාගමනය පාලනය වීම සඳහා රටවල් ජාත්‍යන්තර ප්‍රමිතීන්ට එකඟ වීම වැදගත් වන්නේ ඇයි?", "මගීන්ගේ ආරක්ෂාව, ගමන් කාලසටහන් සම්බන්ධීකරණය හා දේශසීමා පිළිගැනීම තහවුරු කිරීමට", "ගුවන් යානා පියාසර කිරීම තහනම් කිරීමට", "නැව් මුහුදේ ගිල්වීමට", "සංචාරකයන්ට බාධා කිරීමට", "ICAO සහ IMO වැනි ආයතන මගින් ගෝලීය ගුවන් හා සමුද්‍ර ප්‍රවාහන ප්‍රමිතීන් පවත්වාගෙන යයි."),
    q("සංවිධානාත්මක ත්‍රස්තවාදය, මුදල් විශුද්ධිකරණය හා සයිබර් අපරාධ මැඩලීම සඳහා 'ජාත්‍යන්තර සහයෝගීතාව' අත්‍යවශ්‍ය වන්නේ ඇයි?", "එම අපරාධ එක් රටක දේශසීමාවට සීමා නොවී රටවල් ගණනාවක් හරහා ක්‍රියාත්මක වන බැවිනි", "සයිබර් අපරාධ කිසිවෙකුට හානි නොකරන බැවිනි", "ජාත්‍යන්තර නීති අනවශ්‍ය බැවිනි", "අන්තර්ජාලය එක් ගමක පමණක් පවතින බැවිනි", "බුද්ධි තොරතුරු හුවමාරුව හා නීතිමය සහයෝගීතාව මඟින් දේශසීමා ඉක්මවන අපරාධ පාලනය කළ හැකිය."),
    q("විදේශීය ආයෝජකයෙකු හා සත්කාරක රජයක් අතර ආර්ථික ආරවුලක් ඇති වූ විට එය විසඳීමට බොහෝ ගිවිසුම්වල ඇතුළත් කෙරෙන සාමකාමී ක්‍රමය කුමක්ද?", "ජාත්‍යන්තර බේරුම්කරණය (International Arbitration)", "සන්නද්ධ ආක්‍රමණය", "තානාපති කාර්යාල ගිනි තැබීම", "පුරවැසිභාවය අහෝසි කිරීම", "විනිවිද පෙනෙන නීති පද්ධතියක් හා සාධාරණ බේරුම්කරණ යාන්ත්‍රණයක් විදේශ ආයෝජකයන්ගේ විශ්වාසය දිනා ගනී."),
    q("තමන්ගේ රටේ විදේශ ප්‍රතිපත්තිය සම්බන්ධයෙන් පාර්ලිමේන්තුවට සහ මහජනතාවට වගකිව යුතු වීමෙන් ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයකට හිමිවන වාසිය කුමක්ද?", "රහසිගත හෝ ජාතික හිතසුවට පටහැනි ජාත්‍යන්තර ගිවිසුම් ඇතිවීම වැළැක්වීම", "තානාපති සේවය අහෝසි කිරීම", "විදේශ වෙළඳාම නැවැත්වීම", "පුවත්පත් වාරණය කිරීම", "ජාත්‍යන්තර ගිවිසුම්වල විනිවිදභාවය මහජන විශ්වාසය හා ජාතික ආරක්ෂාව තහවුරු කරයි."),
    q("ලෝකයේ බොහෝ රටවල් වර්තමානයේදී 'ද්විපාර්ශ්වික' හා 'කලාපීය' වෙළඳ ගිවිසුම්වලට එළඹීමට උනන්දු වන්නේ ඇයි?", "පුළුල් වෙළඳපොළ ප්‍රවේශයක් ලබා ගැනීම, ආර්ථික වර්ධනය වේගවත් කිරීම හා කලාපීය ස්ථාවරත්වය සඳහාය", "දේශීය කෘෂිකර්මාන්තය විනාශ කිරීමට", "ආනයන සියල්ල නැවැත්වීමට", "රේගු දෙපාර්තමේන්තුව වසා දැමීමට", "සමාන ආර්ථික මට්ටම් ඇති හා අනුපූරක වෙළඳපොළවල් සහිත රටවල් අතර සහයෝගීතාව දෙපාර්ශ්වයටම ලාභදායීය."),
    q("1948 දී ශ්‍රී ලංකාව නිදහස ලැබූ විගස එක්සත් ජාතීන්ගේ සාමාජිකත්වය ලබා ගැනීමට නොහැකි වූයේ ඇයි?", "සීතල යුද සමයේ සෝවියට් සංගමය ආරක්ෂක මණ්ඩලයේදී නිෂේධ බලය භාවිත කළ බැවිනි", "ශ්‍රී ලංකාව සාමාජිකත්වය ඉල්ලුම් නොකළ බැවිනි", "එක්සත් ජාතීන්ගේ සංවිධානය 1960 දී පිහිටුවූ බැවිනි", "ශ්‍රී ලංකාව දූපතක් වූ බැවිනි", "1955 දී බල කඳවුරු අතර ඇතිවූ එකඟතාවකින් පසු රටවල් 16ක් සමඟ ශ්‍රී ලංකාව UN සාමාජිකත්වය ලැබීය."),
    q("ශ්‍රී ලංකාවේ විදේශ සේවයට (Sri Lanka Foreign Service - SLFS) නිලධාරීන් බඳවා ගැනීමේදී ප්‍රධාන වශයෙන් අපේක්ෂා කරන සුදුසුකමක් කුමක්ද?", "තරග විභාග සමත් වීම, භාෂා නිපුණතාව, ජාත්‍යන්තර සබඳතා පිළිබඳ දැනුම හා රාජ්‍යතාන්ත්‍රික හැකියාව", "වෛද්‍ය උපාධිය පමණක් තිබීම", "විදේශීය පුරවැසිභාවය තිබීම", "පළාත් සභා මන්ත්‍රීවරයෙකු වීම", "වෘත්තීය විදේශ සේවා නිලධාරීහු තානාපති කාර්යාලවලදී රටේ අභිලාෂයන් දක්ෂ ලෙස නියෝජනය කරති."),
    q("ජාත්‍යන්තර තලයේදී කුඩා රාජ්‍යයන්ට තම හඬ හා අයිතිවාසිකම් රැකගැනීම සඳහා ඇති හොඳම ආරක්ෂාව කුමක්ද?", "ජාත්‍යන්තර නීතිය, එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය හා බහුපාර්ශ්වික සංවිධාන ශක්තිමත් කිරීම", "න්‍යෂ්ටික අවි තරගයට එක්වීම", "සියලු ජාත්‍යන්තර ගිවිසුම්වලින් ඉවත් වීම", "අසල්වැසි රටවල් ආක්‍රමණය කිරීම", "නීතිය මත පදනම් වූ ජාත්‍යන්තර ක්‍රමයක් කුඩා රටවල ස්වෛරීභාවය ආරක්ෂා කරයි."),
    q("රටක ස්වාභාවික ව්‍යසනයක් හෝ ආර්ථික අර්බුදයක් ඇති වූ විට මිත්‍ර රටවල් හා ජාත්‍යන්තර සංවිධාන ආහාර, ඖෂධ හා ගලවා ගැනීමේ කණ්ඩායම් එවීම හඳුන්වන්නේ කෙසේද?", "මානුෂීය ආධාර රාජ්‍යතාන්ත්‍රිකභාවය (Humanitarian Diplomacy)", "ආර්ථික සම්බාධක පැනවීම", "යුද ප්‍රකාශ කිරීම", "තීරු බදු වැඩි කිරීම", "මානව සංවේදීතාව මත පදනම් වූ මෙවැනි සහයෝගීතා ජාතීන් අතර ස්ථිර මිත්‍රත්වය ගොඩනගයි."),
    q("ගෝලීයකරණය හමුවේ ලොව සියලු දෙනා අන්‍යෝන්‍ය වශයෙන් රඳා පැවතීම නිසා පුද්ගලයෙකු තුළ වර්ධනය විය යුතු පුරවැසි ආකල්පය කුමක්ද?", "තම රටට ආදරය කරන අතරම ලෝක සාමය, පරිසරය හා මානව ගරුත්වය වෙනුවෙන් කැපවීම", "අනෙක් සියලු ජාතීන් කෙරෙහි වෛරය පැතිරවීම", "පරිසර දූෂණය නොසලකා හැරීම", "දේශීය සංස්කෘතියට අගෞරව කිරීම", "දේශප්‍රේමීත්වය හා ගෝලීය වගකීම සමබරව පවත්වා ගැනීම 21 වන සියවසේ පුරවැසියාගේ ලක්ෂණයකි.")
  )
}

